def component_06(data):
    def rounded(num, den, mode):
        if mode == "half_up":
            return (2 * num + den) // (2 * den)
        return num // den
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (seq, event.get("revision", 0), pos)
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)
    balances = dict(data.get("opening", {}))
    for _, e in chosen.values():
        if e.get("void", False):
            continue
        raw = e["price"] * e.get("quantity", 1)
        disc = min(10000, max(0, e.get("discount_bp", 0)))
        net = rounded(raw * (10000 - disc), 10000, data["rounding"])
        tax = rounded(net * e.get("tax_bp", 0), 10000, data["rounding"])
        amount = net + tax
        if e.get("kind") == "refund":
            amount = -amount
        key = e.get("account", "default") + "|" + e.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def component_07(data):
    jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
    by_id = {j["id"]: j for j in jobs}
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_ids = None
    best_value = None
    for subset in combinations(jobs, k):
        ids = tuple(sorted(j["id"] for j in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for j in subset:
            counts[j["group"]] = counts.get(j["group"], 0) + 1
        if any(not (bounds[0] <= counts.get(group, 0) <= bounds[1])
               for group, bounds in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        if any(ordered[i - 1]["end"] > ordered[i]["start"] for i in range(1, k)):
            continue
        value = sum(j["value"] for j in subset)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start = data["start"]
    initial = 0
    for node in required:
        if node == data["source"]:
            initial |= bits[node]
    state = (data["source"], initial, data["coupons"])
    dist = {state: start}
    queue = [(start, data["source"], initial, data["coupons"])]
    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if time != dist.get(state):
            continue
        if node == data["target"] and mask == full and left == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), left - 1))
            for duration, remain in options:
                arrive = depart + duration
                if arrive > data["deadline"]:
                    continue
                nxt = edge["v"]
                newmask = mask | bits.get(nxt, 0)
                ns = (nxt, newmask, remain)
                if arrive < dist.get(ns, float("inf")):
                    dist[ns] = arrive
                    heapq.heappush(queue, (arrive, nxt, newmask, remain))
    return {"arrival": None}


